import { MeshPhysicalNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';
import { primitives } from '@/primitives';
import { text } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Shape, ExtrudeGeometry, OctahedronGeometry, DirectionalLight, AmbientLight, Color } = ctx.THREE;

  // containers for cleanup
  const disposables = [];
  const primitiveHandles = [];

  // root group
  const root = new Group();

  // ---------- BACKDROP ----------
  const backdropGeom = new PlaneGeometry(7, 6);
  const backdropGrad = mix(
    mix(new Color('#0b0b10'), new Color('#12121a'), smoothstep(0.0, 0.6, uv().y)),
    new Color('#16161d'),
    smoothstep(0.6, 1.0, uv().y)
  );
  const backdropMat = new MeshStandardNodeMaterial({ color: backdropGrad });
  const backdrop = new Mesh(backdropGeom, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(backdropGeom, backdropMat);

  // ---------- PRISM ----------
  const side = 1.2;
  const height = Math.sqrt(3) / 2 * side;
  const triShape = new Shape();
  triShape.moveTo(0, 0);
  triShape.lineTo(side, 0);
  triShape.lineTo(side / 2, height);
  triShape.lineTo(0, 0);
  const prismGeom = new ExtrudeGeometry(triShape, { depth: 1.8, bevelEnabled: false });
  const prismMat = new MeshPhysicalNodeMaterial({
    transmission: 1.0,
    thickness: 0.9,
    ior: 1.55,
    roughness: 0.08,
    clearcoat: 0.25,
    clearcoatRoughness: 0.1,
    attenuationColor: new Color('#e8ecf2'),
    attenuationDistance: 2.5,
    iridescence: 1.0,
    iridescenceIOR: 1.3,
    iridescenceThicknessRange: [120, 480],
    side: THREE.DoubleSide
  });
  const prism = new Mesh(prismGeom, prismMat);
  prism.rotation.set(0, THREE.MathUtils.degToRad(20), THREE.MathUtils.degToRad(12));
  root.add(prism);
  disposables.push(prismGeom, prismMat);

  // ---------- EMISSIVE CORE ----------
  const coreGeom = new OctahedronGeometry(0.35);
  const coreMat = new MeshStandardNodeMaterial({
    emissive: new Color('#ff2a38'),
    emissiveIntensity: 2.2,
    metalness: 0,
    roughness: 0.5
  });
  const core = new Mesh(coreGeom, coreMat);
  core.position.set(0, 0, 0);
  root.add(core);
  disposables.push(coreGeom, coreMat);

  // ---------- BACK RIM LIGHT ----------
  const rimLight = new DirectionalLight(new Color('#e8ecf2'), 0.8);
  rimLight.position.set(-5, 2, -5);
  root.add(rimLight);
  disposables.push(rimLight);

  // ---------- CAUSTIC STREAK ----------
  const causticGeom = new PlaneGeometry(2.4, 0.5);
  const causticGrad = mix(
    mix(new Color('#ff2a38'), new Color('#e8ecf2'), smoothstep(0.2, 0.5, uv().x)),
    new Color('#9fb0c4'),
    smoothstep(0.5, 0.8, uv().x)
  );
  const causticMat = new MeshStandardNodeMaterial({
    color: causticGrad,
    transparent: true,
    opacity: 0.35,
    side: THREE.DoubleSide
  });
  const caustic = new Mesh(causticGeom, causticMat);
  caustic.rotation.x = -Math.PI / 2;
  caustic.position.set(0, -1.1, 0);
  root.add(caustic);
  disposables.push(causticGeom, causticMat);

  // ---------- TEXT ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const opts = {
      fontSize: item.typography?.fontSize ?? 68,
      color: item.role === 'headline' ? '#e8ecf2' : '#e8ecf2',
      align: 'left',
      letterSpacingPx: item.typography?.letterSpacing ?? 0
    };
    const txtObj = ctx.fontAtlas.createText(item.text, opts);
    if (item.role === 'headline') {
      txtObj.position.set(-3, -1.75, 0);
    } else {
      txtObj.position.set(-3, -2.25, 0);
    }
    root.add(txtObj);
    disposables.push(txtObj);
  }

  // ---------- CINEMATIC PRIMITIVES ----------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const handle = ctx.primitives[prim.name](root, prim.params);
      primitiveHandles.push(handle);
    }
  }

  // ---------- USER DATA ----------
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    // dispose geometries & materials
    for (const d of disposables) {
      if (d.dispose) d.dispose();
    }
    // cleanup primitives
    for (const h of primitiveHandles) {
      if (h.cleanup) h.cleanup();
    }
    // kill any GSAP timelines (none created here but safe)
    gsap.globalTimeline.clear();
  };

  return root;
}
